//! Create private Unix sockets and authenticate their connected peers.

use super::resources::{current_uid, unavailable, PrivateDirectory, ResourceIdentity};
use super::bootstrap::SocketBootstrapPermit;
use std::fs;
use std::io;
use std::os::fd::AsRawFd;
use std::os::unix::fs::{FileTypeExt, MetadataExt};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};

/// Restore the process mask even when bind fails or unwinds.
struct SocketCreationMask {
    previous: libc::mode_t,
}

impl SocketCreationMask {
    fn restrict(permit: SocketBootstrapPermit) -> io::Result<Self> {
        permit.consume()?;
        // SAFETY: umask has no pointers. Capture under the most restrictive mask
        // before setting the socket mask, so an existing stricter mask is kept.
        let previous = unsafe { libc::umask(0o777) };
        // A Unix socket starts at 0777; deny group/other access and owner execute.
        // The consumed permit proved this is the sole native main thread. This
        // synchronous sequence never spawns a thread or calls application hooks.
        unsafe { libc::umask(previous | 0o177) };
        Ok(Self {
            previous,
        })
    }
}

impl Drop for SocketCreationMask {
    fn drop(&mut self) {
        // SAFETY: restore the captured process mask before bootstrap can continue.
        unsafe { libc::umask(self.previous) };
    }
}

/// Bind under an owner-only mask, restoring the prior process mask on every outcome.
fn bind_private_listener(path: &Path, permit: SocketBootstrapPermit) -> io::Result<UnixListener> {
    let _mask = SocketCreationMask::restrict(permit)?;
    UnixListener::bind(path)
}

/// New settings endpoint; never bind the historical singleton address.
/// Cleanup is explicit and refuses resources whose inode/owner changed.
// @spec FR-004: Private settings endpoint — .specs/features/008-settings-cli/spec.md#fr-004
pub(crate) struct PrivateSocket {
    path: PathBuf,
    listener: Option<UnixListener>,
    identity: ResourceIdentity,
    directory: PrivateDirectory,
}

impl PrivateSocket {
    /// Bind only a simple basename within a validated injected private directory.
    /// Never delete a stale socket or attempt to notify an existing instance.
    pub(crate) fn bind(directory: &PrivateDirectory, filename: &str, permit: SocketBootstrapPermit) -> io::Result<Self> {
        Self::bind_with_creation_hook(directory, filename, permit, |_| Ok(()))
    }

    /// Allow boundary tests to replace a newly created resource before revalidation.
    pub(crate) fn bind_with_creation_hook(
        directory: &PrivateDirectory,
        filename: &str,
        permit: SocketBootstrapPermit,
        after_creation: impl FnOnce(&Path) -> io::Result<()>,
    ) -> io::Result<Self> {
        if filename.is_empty() || filename.contains('/') || filename == "." || filename == ".." {
            return Err(unavailable());
        }
        directory.validate_current()?;
        let path = directory.path().join(filename);
        let listener = bind_private_listener(&path, permit)?;
        let created = fs::symlink_metadata(&path)?;
        validate_private_socket(&created)?;
        let identity = ResourceIdentity::from_metadata(&created);
        after_creation(&path)?;
        directory.validate_current()?;
        let metadata = fs::symlink_metadata(&path)?;
        validate_private_socket(&metadata)?;
        if ResourceIdentity::from_metadata(&metadata) != identity {
            return Err(unavailable());
        }
        Ok(Self {
            path,
            listener: Some(listener),
            identity,
            directory: PrivateDirectory::open(directory.path())?,
        })
    }

    /// Return the new settings endpoint path.
    pub(crate) fn path(&self) -> &Path {
        &self.path
    }

    /// Set nonblocking mode so the transport can enforce a total deadline.
    pub(crate) fn set_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.listener
            .as_ref()
            .ok_or_else(unavailable)?
            .set_nonblocking(nonblocking)
    }

    /// Accept a connection without executing any received command.
    pub(crate) fn accept(&self) -> io::Result<(UnixStream, std::os::unix::net::SocketAddr)> {
        self.directory.validate_current()?;
        self.listener.as_ref().ok_or_else(unavailable)?.accept()
    }

    /// Close only this listener; retain its socket name for later proven reclamation.
    /// No stat/unlink pair can atomically exclude same-UID pathname replacement.
    /// Routing must prove the lease is dead before reclaiming a stale endpoint.
    pub(crate) fn close_owned_listener(&mut self) -> io::Result<()> {
        self.directory.validate_current()?;
        let metadata = fs::symlink_metadata(&self.path)?;
        if !metadata.file_type().is_socket()
            || ResourceIdentity::from_metadata(&metadata) != self.identity
        {
            return Err(unavailable());
        }
        self.listener.take();
        Ok(())
    }
}

fn validate_private_socket(metadata: &fs::Metadata) -> io::Result<()> {
    if !metadata.file_type().is_socket()
        || metadata.uid() != current_uid()
        || metadata.mode() & 0o777 != 0o600
        || metadata.nlink() != 1
    {
        return Err(unavailable());
    }
    Ok(())
}

/// Authenticate the effective UID of the connected local peer.
pub(crate) fn verify_peer(stream: &UnixStream) -> io::Result<()> {
    verify_peer_uid(stream, current_uid())
}

/// Check a peer against the endpoint owner; exposed to deterministic identity tests.
pub(crate) fn verify_peer_uid(stream: &UnixStream, expected_uid: u32) -> io::Result<()> {
    if peer_uid(stream)? != expected_uid {
        return Err(unavailable());
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn peer_uid(stream: &UnixStream) -> io::Result<u32> {
    let mut uid: libc::uid_t = 0;
    let mut gid: libc::gid_t = 0;
    // SAFETY: the live fd and initialized UID/GID outputs are valid for getpeereid.
    if unsafe { libc::getpeereid(stream.as_raw_fd(), &mut uid, &mut gid) } != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(uid)
}

#[cfg(target_os = "linux")]
fn peer_uid(stream: &UnixStream) -> io::Result<u32> {
    let mut credentials: libc::ucred = unsafe { std::mem::zeroed() };
    let mut length = std::mem::size_of::<libc::ucred>() as libc::socklen_t;
    // SAFETY: the writable ucred buffer matches length, and stream owns the live fd.
    if unsafe {
        libc::getsockopt(
            stream.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_PEERCRED,
            &mut credentials as *mut _ as *mut libc::c_void,
            &mut length,
        )
    } != 0
    {
        return Err(io::Error::last_os_error());
    }
    if length as usize != std::mem::size_of::<libc::ucred>() {
        return Err(unavailable());
    }
    Ok(credentials.uid)
}

//! Native single-thread bootstrap authority for process-wide socket creation masks.

use super::resources::unavailable;
use std::io;
use std::marker::PhantomData;
use std::rc::Rc;

/// Actual native process state; uncertainty is represented by an error.
pub(crate) struct BootstrapContext {
    pub(crate) is_main_thread: bool,
    pub(crate) native_threads: usize,
}

/// One bind authority acquired before Tauri/Tokio starts; neither cloneable nor Send.
// @spec FR-004: Single-thread private socket bootstrap — .specs/features/008-settings-cli/spec.md#fr-004
pub(crate) struct SocketBootstrapPermit {
    _not_send: PhantomData<Rc<()>>,
}

impl SocketBootstrapPermit {
    /// Authorize only the real native main thread while it is the process's sole thread.
    pub(crate) fn acquire() -> io::Result<Self> {
        require_single_main_thread()?;
        Ok(Self {
            _not_send: PhantomData,
        })
    }

    /// Consume once, rechecking immediately before the mask/bind sequence.
    pub(super) fn consume(self) -> io::Result<()> {
        require_single_main_thread()
    }
}

fn require_single_main_thread() -> io::Result<()> {
    let context = observe_native_context()?;
    if !context.is_main_thread || context.native_threads != 1 {
        return Err(unavailable());
    }
    Ok(())
}

/// Observe OS thread identity/count without a caller-provided state assertion.
#[cfg(target_os = "macos")]
pub(crate) fn observe_native_context() -> io::Result<BootstrapContext> {
    // SAFETY: pthread_main_np has no parameters and observes the calling thread.
    let is_main_thread = unsafe { libc::pthread_main_np() } == 1;
    Ok(BootstrapContext {
        is_main_thread,
        native_threads: macos_thread_count()?,
    })
}

#[cfg(target_os = "macos")]
unsafe extern "C" {
    static mach_task_self_: u32;
    fn task_threads(task: u32, threads: *mut *mut u32, count: *mut u32) -> i32;
    fn mach_port_deallocate(task: u32, port: u32) -> i32;
    fn vm_deallocate(task: u32, address: usize, size: usize) -> i32;
}

#[cfg(target_os = "macos")]
fn macos_thread_count() -> io::Result<usize> {
    let mut threads = std::ptr::null_mut();
    let mut count = 0;
    // SAFETY: SDK mach/task.h ABI; task_threads owns the returned VM array and
    // grants a send right for each thread. Both resources are released below.
    let task = unsafe { mach_task_self_ };
    if unsafe { task_threads(task, &mut threads, &mut count) } != 0 {
        return Err(unavailable());
    }
    if count == 0 || threads.is_null() {
        return Err(unavailable());
    }
    release_thread_array(task, threads, count)?;
    Ok(count as usize)
}

#[cfg(target_os = "macos")]
fn release_thread_array(task: u32, threads: *mut u32, count: u32) -> io::Result<()> {
    let mut failed = false;
    // SAFETY: task_threads returned exactly count initialized ports in this VM
    // allocation. Release every send right before freeing the allocation once.
    unsafe {
        for port in std::slice::from_raw_parts(threads, count as usize) {
            failed |= mach_port_deallocate(task, *port) != 0;
        }
        failed |= vm_deallocate(
            task,
            threads as usize,
            count as usize * std::mem::size_of::<u32>(),
        ) != 0;
    }
    if failed {
        return Err(unavailable());
    }
    Ok(())
}

/// The initial Linux thread's native TID equals PID; /proc enumerates native threads.
#[cfg(target_os = "linux")]
pub(crate) fn observe_native_context() -> io::Result<BootstrapContext> {
    // SAFETY: gettid/getpid take no pointers and only observe this process.
    let is_main_thread = unsafe { libc::gettid() == libc::getpid() };
    let native_threads = std::fs::read_dir("/proc/self/task")?.try_fold(0, |count, entry| {
        entry?;
        Ok::<usize, io::Error>(count + 1)
    })?;
    Ok(BootstrapContext {
        is_main_thread,
        native_threads,
    })
}

#[cfg(not(any(target_os = "macos", target_os = "linux")))]
pub(crate) fn observe_native_context() -> io::Result<BootstrapContext> {
    Err(unavailable())
}

//! Test-only native driver importing the exact production Unix resource modules.

#[cfg(unix)]
#[path = "../src/settings_service/platform_unix.rs"]
mod platform_unix;
#[cfg(unix)]
#[path = "settings_socket_bootstrap/socket_cases.rs"]
mod socket_cases;
#[cfg(unix)]
#[path = "settings_socket_bootstrap/guard_cases.rs"]
mod guard_cases;

#[cfg(unix)]
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let case = std::env::args().nth(1).ok_or("missing test scenario")?;
    match case.as_str() {
        "threaded_bind_is_refused" => guard_cases::threaded_bind_is_refused()?,
        "private_directory_refuses_permissions_alias_and_replacement" => socket_cases::private_directory_refuses_permissions_alias_and_replacement()?,
        "new_socket_authenticates_peer_and_cleans_only_owned_inode" => socket_cases::new_socket_authenticates_peer_and_cleans_only_owned_inode()?,
        "close_retains_socket_and_releases_lock_by_lifetime" => socket_cases::close_retains_socket_and_releases_lock_by_lifetime()?,
        "lock_and_file_refuse_hostile_aliases" => socket_cases::lock_and_file_refuse_hostile_aliases()?,
        _ => return Err("unknown test scenario".into()),
    }
    println!("{}",serde_json::json!({"ok":true,"case":case,"platform":std::env::consts::OS}));
    Ok(())
}

#[cfg(not(unix))]
fn main() {
    eprintln!("Unix bootstrap driver is unsupported on this target");
    std::process::exit(1);
}

//! Actual private-socket scenarios executed in a fresh single-thread process.

use super::platform_unix::{current_uid, PrivateDirectory, PrivateSocket, StartupFence};
use std::{fs,io};
use std::os::unix::fs::{MetadataExt,PermissionsExt,symlink};
use std::os::unix::net::{UnixListener,UnixStream};

fn fixture() -> io::Result<(tempfile::TempDir,PrivateDirectory)> {
 let temp=tempfile::Builder::new().prefix("hsb-").tempdir_in("/tmp")?;
 fs::set_permissions(temp.path(),fs::Permissions::from_mode(0o700))?;
 let directory=PrivateDirectory::open(&temp.path().canonicalize()?)?;
 Ok((temp,directory))
}

pub(super) fn private_directory_refuses_permissions_alias_and_replacement(
) -> Result<(), Box<dyn std::error::Error>> {
    let (_temp, directory) = fixture()?;
    fs::set_permissions(directory.path(), fs::Permissions::from_mode(0o755))?;
    assert!(PrivateDirectory::open(directory.path()).is_err());
    fs::set_permissions(directory.path(), fs::Permissions::from_mode(0o700))?;
    let link = directory.path().join("alias");
    symlink(directory.path(), &link)?;
    assert!(PrivateDirectory::open(&link).is_err());
    fs::remove_file(link)?;
    let moved = directory.path().with_extension("moved");
    let endpoint = directory.path().join("settings.sock");
    fs::rename(directory.path(), &moved)?;
    fs::create_dir(directory.path())?;
    fs::set_permissions(directory.path(), fs::Permissions::from_mode(0o700))?;
    assert!(PrivateSocket::bind(&directory, "settings.sock").is_err());
    assert!(!endpoint.exists());
    fs::remove_dir_all(moved)?;
    Ok(())
}

pub(super) fn new_socket_authenticates_peer_and_cleans_only_owned_inode(
) -> Result<(), Box<dyn std::error::Error>> {
    let (_temp, directory) = fixture()?;
    let mut socket = PrivateSocket::bind(&directory, "settings.sock")?;
    assert_eq!(fs::symlink_metadata(socket.path())?.mode() & 0o777, 0o600);
    assert!(PrivateSocket::bind(&directory, "settings.sock").is_err());
    socket.set_nonblocking(true)?;
    assert_eq!(
        socket.accept().expect_err("no client yet").kind(),
        std::io::ErrorKind::WouldBlock
    );
    let client = UnixStream::connect(socket.path())?;
    let (server, _) = socket.accept()?;
    platform_unix::verify_peer(&server)?;
    assert!(platform_unix::verify_peer_uid(&server, current_uid().wrapping_add(1)).is_err());
    drop(client);
    fs::remove_file(socket.path())?;
    fs::write(socket.path(), b"replacement")?;
    assert!(socket.close_owned_listener().is_err());
    assert_eq!(fs::read(socket.path())?, b"replacement");
    Ok(())
}

pub(super) fn close_retains_socket_and_releases_lock_by_lifetime() -> Result<(), Box<dyn std::error::Error>> {
    let (_temp, directory) = fixture()?;
    let mut socket = PrivateSocket::bind(&directory, "settings.sock")?;
    let path = socket.path().to_path_buf();
    socket.close_owned_listener()?;
    assert!(path.exists());
    assert!(UnixStream::connect(&path).is_err());
    let fence = StartupFence::acquire(&directory, "instance.lock")?;
    assert!(StartupFence::acquire(&directory, "instance.lock").is_err());
    fence.validate_current()?;
    drop(fence);
    assert!(StartupFence::acquire(&directory, "instance.lock").is_ok());
    Ok(())
}

pub(super) fn lock_and_file_refuse_hostile_aliases() -> Result<(), Box<dyn std::error::Error>> {
    let (_temp, directory) = fixture()?;
    let target = directory.path().join("retained");
    fs::write(&target, b"retained")?;
    symlink(&target, directory.path().join("instance.lock"))?;
    assert!(StartupFence::acquire(&directory, "instance.lock").is_err());
    assert_eq!(fs::read(target)?, b"retained");
    Ok(())
}

pub(super) fn bind_rejects_regular_replacement_without_changing_permissions() -> io::Result<()> {
    let (_temp, directory) = fixture()?;
    let path = directory.path().join("settings.sock");
    let outcome = PrivateSocket::bind_with_creation_hook(&directory, "settings.sock", |path| {
        fs::remove_file(path)?;
        fs::write(path, b"retained")?;
        fs::set_permissions(path, fs::Permissions::from_mode(0o640))
    });
    assert!(outcome.is_err());
    assert_eq!(fs::symlink_metadata(&path)?.mode() & 0o777, 0o640);
    assert_eq!(fs::read(path)?, b"retained");
    Ok(())
}

pub(super) fn bind_rejects_socket_replacement_with_matching_owner_and_mode() -> io::Result<()> {
    let (_temp, directory) = fixture()?;
    let mut replacement = None;
    let outcome = PrivateSocket::bind_with_creation_hook(&directory, "settings.sock", |path| {
        fs::remove_file(path)?;
        replacement = Some(UnixListener::bind(path)?);
        fs::set_permissions(path,fs::Permissions::from_mode(0o600))?;
        Ok(())
    });
    assert!(outcome.is_err());
    assert_eq!(
        fs::symlink_metadata(directory.path().join("settings.sock"))?.mode() & 0o777,
        0o600
    );
    assert!(replacement.is_some());
    Ok(())
}

pub(super) fn failed_bind_restores_the_previous_creation_mask() -> io::Result<()> {
    let (_temp, directory) = fixture()?;
    let path = directory.path().join("retained");
    fs::write(&path, b"retained")?;
    // SAFETY: this isolated driver runs these mask observations on its sole thread.
    let previous = unsafe { libc::umask(0o777) };
    unsafe { libc::umask(previous) };
    assert!(PrivateSocket::bind(&directory,"retained").is_err());
    let observed = unsafe { libc::umask(0o777) };
    unsafe { libc::umask(observed) };
    assert_eq!(observed, previous);
    assert_eq!(fs::read(path)?, b"retained");
    Ok(())
}

//! Real OS multithread refusal scenario; no caller-provided thread-state token.

use super::platform_unix::{PrivateDirectory, PrivateSocket};
use std::os::unix::fs::PermissionsExt;

pub(super) fn threaded_bind_is_refused() -> Result<(),Box<dyn std::error::Error>> {
    let temp=tempfile::Builder::new().prefix("hsb-").tempdir_in("/tmp")?;
    std::fs::set_permissions(temp.path(),std::fs::Permissions::from_mode(0o700))?;
    let directory=PrivateDirectory::open(&temp.path().canonicalize()?)?;
    let (ready_tx,ready_rx)=std::sync::mpsc::channel();
    let (stop_tx,stop_rx)=std::sync::mpsc::channel();
    let worker=std::thread::spawn(move || {
        ready_tx.send(()).expect("ready receiver");
        stop_rx.recv().expect("stop sender");
    });
    ready_rx.recv_timeout(std::time::Duration::from_secs(5))?;
    let result=PrivateSocket::bind(&directory,"settings.sock");
    stop_tx.send(())?;
    worker.join().map_err(|_|"worker panic")?;
    assert!(result.is_err(),"a threaded process must never mutate its creation mask");
    assert!(!directory.path().join("settings.sock").exists());
    Ok(())
}
